// Pattern: GetAuditLogList.cs
public record Query : IQuery<PaginationResDto<AllocationRecordDto>>
{
    public Guid OrderId { get; init; }
    public List<AllocationStatus>? Statuses { get; init; }
    public string? Item { get; init; }
    public string? Location { get; init; }
    public DateTime? FromDate { get; init; }
    public DateTime? ToDate { get; init; }
    public int Page { get; init; } = 1;
    public int PageSize { get; init; } = 20;
}

public class QueryHandler(IAppDbContext context) : IQueryHandler<Query, PaginationResDto<AllocationRecordDto>>
{
    public async Task<PaginationResDto<AllocationRecordDto>> HandleAsync(Query query, CancellationToken ct = default)
    {
        var queryable = context.AllocationRecords
            .AsNoTracking()
            .Where(x => x.OrderDetail.OrderHeaderId == query.OrderId)
            .WhereIf(query.Statuses is { Count: > 0 }, x => query.Statuses!.Contains(x.Status))
            .WhereIf(!string.IsNullOrWhiteSpace(query.Item), x =>
                x.OrderDetail.Item.Code.Contains(query.Item!) ||
                x.OrderDetail.Item.Name.Contains(query.Item!))
            .WhereIf(!string.IsNullOrWhiteSpace(query.Location), x =>
                x.InventDim.Location != null && x.InventDim.Location.Code.Contains(query.Location!))
            .WhereIf(query.FromDate.HasValue, x => x.CreatedTime >= query.FromDate)
            .WhereIf(query.ToDate.HasValue, x => x.CreatedTime <= query.ToDate);

        var totalCount = await queryable.CountAsync(ct);

        var items = await queryable
            .OrderByDescending(x => x.CreatedTime)
            .Skip((query.Page - 1) * query.PageSize)
            .Take(query.PageSize)
            .Select(x => new AllocationRecordDto(
                x.Id,
                x.OrderDetail.Item.Code,
                x.OrderDetail.Item.Name,
                x.InventDim.Location != null ? x.InventDim.Location.Code : null,
                x.InventDim.Location != null ? x.InventDim.Location.Name : null,
                x.InventDim.Warehouse.Code,
                x.InventDim.Lot != null ? x.InventDim.Lot.LotCode : null,
                x.AllocatedQtyKg,
                x.AllocationMethod.ToString(),
                x.Status.ToString(),
                x.ExpiresAt,
                x.CreatedTime,
                x.CreatedBy
            ))
            .ToListAsync(ct);

        return new PaginationResDto<AllocationRecordDto>(items, totalCount, query.Page, query.PageSize);
    }
}

