[HttpGet("{orderId:guid}/allocation-records")]
[ProducesResponseType(typeof(ApiResult<PaginationResDto<AllocationRecordDto>>), StatusCodes.Status200OK)]
public async Task<IActionResult> GetAllocationRecords(
    [FromRoute] Guid orderId,
    [FromQuery] string? statuses = null,
    [FromQuery] string? item = null,
    [FromQuery] string? location = null,
    [FromQuery] DateTime? fromDate = null,
    [FromQuery] DateTime? toDate = null,
    [FromQuery] int page = 1,
    [FromQuery] int pageSize = 20,
    CancellationToken ct = default)
{
    var statusList = string.IsNullOrWhiteSpace(statuses)
        ? null
        : statuses.Split(',').Select(s => Enum.Parse<AllocationStatus>(s.Trim(), true)).ToList();

    var query = new GetAllocationsByOrder.Query
    {
        OrderId = orderId,
        Statuses = statusList,
        Item = item,
        Location = location,
        FromDate = fromDate,
        ToDate = toDate,
        Page = page,
        PageSize = pageSize
    };
    var result = await dispatcher.QueryAsync(query, ct);
    return Ok(ApiResult<PaginationResDto<AllocationRecordDto>>.Success(result));
}

