// frontend/src/features/orders/api/allocation-records.ts
import { apiClient } from '@/lib/api-client'
import type { AllocationRecord, AllocationRecordFilters } from '../data/allocation-schema'

export interface AllocationRecordPage {
  items: AllocationRecord[]
  totalCount: number
  page: number
  pageSize: number
  totalPages: number
  hasPreviousPage: boolean
  hasNextPage: boolean
}

export const allocationRecordsApi = {
  getByOrder: async (orderId: string, filters: AllocationRecordFilters): Promise<AllocationRecordPage> => {
    const params = new URLSearchParams()
    if (filters.statuses?.length) params.set('statuses', filters.statuses.join(','))
    if (filters.item) params.set('item', filters.item)
    if (filters.location) params.set('location', filters.location)
    if (filters.fromDate) params.set('fromDate', filters.fromDate)
    if (filters.toDate) params.set('toDate', filters.toDate)
    params.set('page', String(filters.page ?? 1))
    params.set('pageSize', String(filters.pageSize ?? 20))
    const response = await apiClient.get(`/orders/${orderId}/allocation-records?${params.toString()}`)
    return response.data.data
  },
}
